def compute(vars):
    first_year_payment = vars["v1"]
    total_lease_payments = vars["v2"]

    if total_lease_payments == 0:
        return None

    ratio = first_year_payment / total_lease_payments
    percentage = ratio * 100

    return {
        "value": percentage,
        "trace": {
            "first_year_payment": first_year_payment,
            "total_lease_payments": total_lease_payments,
            "ratio": ratio,
            "output_meta": {
                "currency": None,
                "scale": None,
                "unit": "percentage"
            }
        }
    }
